1	import fs from 'fs';
2	import path from 'path';
3	import { parseFrontmatter } from './frontmatter';
4	import { renderMarkdown } from './markdown';
5	import { getTemplateEngine } from './templates';
6	import { Page } from './types';
7	
8	export interface BuildOptions {
9	  contentDir: string;
10	  outputDir: string;
11	  templatesDir?: string;
12	}
13	
14	export interface BuildResult {
15	  pages: Page[];
16	  outputDir: string;
17	}
18	
19	function defaultTemplatesDir(): string {
20	  return path.resolve(process.cwd(), 'templates');
21	}
22	
23	function slugify(filename: string): string {
24	  return filename.replace(/\.md$/i, '');
25	}
26	
27	function normalizeTags(tags: unknown): string[] {
28	  if (Array.isArray(tags)) return tags.map((tag) => String(tag));
29	  if (typeof tags === 'string' && tags.length > 0) return [tags];
30	  return [];
31	}
32	
33	export function findMarkdownFiles(contentDir: string): string[] {
34	  if (!fs.existsSync(contentDir)) {
35	    throw new Error(`Content directory not found: ${contentDir}`);
36	  }
37	  return fs
38	    .readdirSync(contentDir)
39	    .filter((file) => file.toLowerCase().endsWith('.md'))
40	    .sort();
41	}
42	
43	export function buildPage(contentDir: string, filename: string, templatesDir: string = defaultTemplatesDir()): Page {
44	  const filePath = path.join(contentDir, filename);
45	  const raw = fs.readFileSync(filePath, 'utf-8');
46	  const { data, content } = parseFrontmatter(raw);
47	  const body = renderMarkdown(content);
48	  const slug = slugify(filename);
49	  const title = typeof data.title === 'string' && data.title.length > 0 ? data.title : slug;
50	  const date = typeof data.date === 'string' ? data.date : undefined;
51	  const tags = normalizeTags(data.tags);
52	  const outputPath = `${slug}.html`;
53	  const templateName = typeof data.template === 'string' && data.template.trim().length > 0 ? data.template.trim() : 'default';
54	  const engine = getTemplateEngine(templatesDir);
55	  const html = engine.renderPage({ title, date, tags, body }, templateName);
56	  return { slug, title, date, tags, html, outputPath, template: templateName };
57	}
58	
59	export function build(options: BuildOptions): BuildResult {
60	  const { contentDir, outputDir, templatesDir = defaultTemplatesDir() } = options;
61	  const files = findMarkdownFiles(contentDir);
62	  const pages = files.map((file) => buildPage(contentDir, file, templatesDir));
63	
64	  fs.mkdirSync(outputDir, { recursive: true });
65	  for (const page of pages) {
66	    fs.writeFileSync(path.join(outputDir, page.outputPath), page.html, 'utf-8');
67	  }
68	  const engine = getTemplateEngine(templatesDir);
69	  fs.writeFileSync(path.join(outputDir, 'index.html'), engine.renderIndex(pages), 'utf-8');
70	
71	  return { pages, outputDir };
72	}
