1	import fs from 'fs';
2	import http from 'http';
3	import path from 'path';
4	import chokidar, { FSWatcher } from 'chokidar';
5	import { WebSocket, WebSocketServer } from 'ws';
6	import { build, BuildOptions } from './build';
7	import { clearTemplateEngineCache } from './templates';
8	
9	export interface ServeOptions extends BuildOptions {
10	  port?: number;
11	}
12	
13	export interface DevServer {
14	  port: number;
15	  close(): Promise<void>;
16	}
17	
18	const DEFAULT_PORT = 3000;
19	const LIVE_RELOAD_PATH = '/__livereload';
20	const REBUILD_DEBOUNCE_MS = 100;
21	
22	const CONTENT_TYPES: Record<string, string> = {
23	  '.html': 'text/html; charset=utf-8',
24	  '.css': 'text/css; charset=utf-8',
25	  '.js': 'text/javascript; charset=utf-8',
26	  '.json': 'application/json; charset=utf-8',
27	  '.svg': 'image/svg+xml',
28	  '.png': 'image/png',
29	  '.jpg': 'image/jpeg',
30	  '.jpeg': 'image/jpeg',
31	  '.gif': 'image/gif',
32	  '.ico': 'image/x-icon',
33	  '.txt': 'text/plain; charset=utf-8',
34	};
35	
36	const LIVE_RELOAD_SCRIPT = `
37	<script>
38	(function () {
39	  var socket = new WebSocket('ws://' + location.host + '${LIVE_RELOAD_PATH}');
40	  socket.addEventListener('message', function (event) {
41	    if (event.data === 'reload') {
42	      location.reload();
43	    }
44	  });
45	})();
46	</script>
47	`;
48	
49	function injectLiveReload(html: string): string {
50	  if (html.includes('</body>')) {
51	    return html.replace('</body>', `${LIVE_RELOAD_SCRIPT}</body>`);
52	  }
53	  return html + LIVE_RELOAD_SCRIPT;
54	}
55	
56	function resolveRequestedFile(outputDir: string, urlPath: string): string | undefined {
57	  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
58	  let relative = decoded === '/' ? '/index.html' : decoded;
59	  if (relative.endsWith('/')) relative += 'index.html';
60	
61	  const root = path.resolve(outputDir);
62	  const resolved = path.resolve(root, `.${relative}`);
63	  if (resolved !== root && !resolved.startsWith(root + path.sep)) {
64	    return undefined;
65	  }
66	  return resolved;
67	}
68	
69	function sendNotFound(res: http.ServerResponse): void {
70	  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
71	  res.end('404 Not Found');
72	}
73	
74	function serveFile(outputDir: string, urlPath: string, res: http.ServerResponse): void {
75	  const filePath = resolveRequestedFile(outputDir, urlPath);
76	  if (!filePath || !fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
77	    sendNotFound(res);
78	    return;
79	  }
80	
81	  const ext = path.extname(filePath).toLowerCase();
82	  const contentType = CONTENT_TYPES[ext] ?? 'application/octet-stream';
83	
84	  if (ext === '.html') {
85	    const html = fs.readFileSync(filePath, 'utf-8');
86	    res.writeHead(200, { 'Content-Type': contentType });
87	    res.end(injectLiveReload(html));
88	    return;
89	  }
90	
91	  res.writeHead(200, { 'Content-Type': contentType });
92	  fs.createReadStream(filePath).pipe(res);
93	}
94	
95	export async function startServer(options: ServeOptions): Promise<DevServer> {
96	  const {
97	    contentDir,
98	    outputDir,
99	    templatesDir = path.resolve(process.cwd(), 'templates'),
100	    port = DEFAULT_PORT,
101	  } = options;
102	
103	  const runBuild = (): void => {
104	    try {
105	      clearTemplateEngineCache(templatesDir);
106	      build({ contentDir, outputDir, templatesDir });
107	    } catch (err) {
108	      console.error('Rebuild failed:', err instanceof Error ? err.message : err);
109	    }
110	  };
111	
112	  runBuild();
113	
114	  const httpServer = http.createServer((req, res) => {
115	    serveFile(outputDir, req.url ?? '/', res);
116	  });
117	
118	  const wss = new WebSocketServer({ server: httpServer, path: LIVE_RELOAD_PATH });
119	
120	  const broadcastReload = (): void => {
121	    for (const client of wss.clients) {
122	      if (client.readyState === WebSocket.OPEN) {
123	        client.send('reload');
124	      }
125	    }
126	  };
127	
128	  let rebuildTimer: NodeJS.Timeout | undefined;
129	  const scheduleRebuild = (): void => {
130	    if (rebuildTimer) clearTimeout(rebuildTimer);
131	    rebuildTimer = setTimeout(() => {
132	      runBuild();
133	      broadcastReload();
134	    }, REBUILD_DEBOUNCE_MS);
135	  };
136	
137	  const watcher: FSWatcher = chokidar.watch([contentDir, templatesDir], {
138	    ignoreInitial: true,
139	  });
140	  watcher.on('add', scheduleRebuild);
141	  watcher.on('change', scheduleRebuild);
142	  watcher.on('unlink', scheduleRebuild);
143	
144	  const listening = new Promise<number>((resolve, reject) => {
145	    httpServer.once('error', reject);
146	    httpServer.listen(port, () => {
147	      httpServer.removeListener('error', reject);
148	      const address = httpServer.address();
149	      resolve(typeof address === 'object' && address ? address.port : port);
150	    });
151	  });
152	  const watcherReady = new Promise<void>((resolve) => watcher.once('ready', resolve));
153	
154	  const [actualPort] = await Promise.all([listening, watcherReady]);
155	
156	  return {
157	    port: actualPort,
158	    close: async () => {
159	      if (rebuildTimer) clearTimeout(rebuildTimer);
160	      await watcher.close();
161	      await new Promise<void>((res) => wss.close(() => res()));
162	      for (const client of wss.clients) client.terminate();
163	      await new Promise<void>((res, rej) => httpServer.close((err) => (err ? rej(err) : res())));
164	    },
165	  };
166	}
