18	      path.join(contentDir, 'first-post.md'),
19	      `---
20	title: First Post
21	date: 2024-01-01
22	tags: [intro, news]
23	---
24	# Hello
25	
26	This is the **first** post.`
27	    );
28	    fs.writeFileSync(
29	      path.join(contentDir, 'second-post.md'),
30	      `---
31	title: Second Post
32	date: 2024-02-01
33	tags: update
34	---
