input.content:
import { Page } from './types';

export interface PluginContext {
  contentDir: string;
  outputDir?: string;
  templatesDir: string;
}

/**
 * Mutable working state for a single content file as it flows through the
 * plugin pipeline. Plugins read/write these fields in place; the engine
 * converts the final draft into a public `Page` once every plugin has run.
 */
export interface PageDraft {
  slug: string;
  filename: string;
  data: Record<string, unknown>;
  content: string;
  title: string;
  date?: string;
  tags: string[];
  template: string;
  outputPath: string;
  body: string;
  html: string;
}

export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void | Promise<void>;
  beforeBuild?(ctx: PluginContext): void;
  onFile?(page: PageDraft, ctx: PluginContext): void;
  afterBuild?(pages: Page[], ctx: PluginContext): void;
  onEnd?(ctx: PluginContext): void | Promise<void>;
}

import fs from 'fs';
import path from 'path';
import { parseFrontmatter } from './frontmatter';
import { Page } from './types';
import { Plugin, PluginContext, PageDraft } from './plugin';

function slugify(filename: string): string {
  return filename.replace(/\.md$/i, '');
}

function normalizeTags(tags: unknown): string[] {
  if (Array.isArray(tags)) return tags.map((tag) => String(tag));
  if (typeof tags === 'string' && tags.length > 0) return [tags];
  return [];
}

export function findMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }
  return fs
    .readdirSync(contentDir)
    .filter((file) => file.toLowerCase().endsWith('.md'))
    .sort();
}

function makeDraft(contentDir: string, filename: string): PageDraft {
  const filePath = path.join(contentDir, filename);
  const raw = fs.readFileSync(filePath, 'utf-8');
  const { data, content } = parseFrontmatter(raw);
  const slug = slugify(filename);
  const title = typeof data.title === 'string' && data.title.length > 0 ? data.title : slug;
  const date = typeof data.date === 'string' ? data.date : undefined;
  const tags = normalizeTags(data.tags);
  const outputPath = `${slug}.html`;
  const template =
    typeof data.template === 'string' && data.template.trim().length > 0 ? data.template.trim() : 'default';
  return { slug, filename, data, content, title, date, tags, template, outputPath, body: '', html: '' };
}

function toPage(draft: PageDraft): Page {
  return {
    slug: draft.slug,
    title: draft.title,
    date: draft.date,
    tags: draft.tags,
    html: draft.html,
    outputPath: draft.outputPath,
    template: draft.template,
  };
}

/**
 * Orchestrates the plugin pipeline. `onStart`/`onEnd` bracket the engine's
 * whole lifetime (e.g. a dev server's process); `beforeBuild`/`onFile`/
 * `afterBuild` run once per build pass and stay fully synchronous so the
 * public `buildPage`/`build` API can remain synchronous too.
 */
export class SSGEngine {
  constructor(private readonly plugins: Plugin[]) {}

  async start(ctx: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onStart?.(ctx);
    }
  }

  async end(ctx: PluginContext): Promise<void> {
    for (const plugin of this.plugins) {
      await plugin.onEnd?.(ctx);
    }
  }

  buildFile(contentDir: string, filename: string, ctx: PluginContext): Page {
    const draft = makeDraft(contentDir, filename);
    for (const plugin of this.plugins) {
      plugin.onFile?.(draft, ctx);
    }
    return toPage(draft);
  }

  runBuild(ctx: PluginContext): Page[] {
    for (const plugin of this.plugins) {
      plugin.beforeBuild?.(ctx);
    }
    const files = findMarkdownFiles(ctx.contentDir);
    const pages = files.map((file) => this.buildFile(ctx.contentDir, file, ctx));
    for (const plugin of this.plugins) {
      plugin.afterBuild?.(pages, ctx);
    }
    return pages;
  }
}

import { renderMarkdown } from '../src/markdown';
import { Plugin } from '../src/plugin';

/** Renders each page's raw Markdown content into an HTML body fragment. */
export function markdownPlugin(): Plugin {
  return {
    name: 'markdown',
    onFile(page) {
      page.body = renderMarkdown(page.content);
    },
  };
}

import fs from 'fs';
import path from 'path';
import { Plugin } from '../src/plugin';
import { getTemplateEngine } from '../src/templates';

/**
 * Wraps each page's rendered body in its Handlebars layout, and writes the
 * site index page once every file in a build pass has been processed.
 */
export function templatePlugin(): Plugin {
  return {
    name: 'template',
    onFile(page, ctx) {
      const engine = getTemplateEngine(ctx.templatesDir);
      page.html = engine.renderPage(
        { title: page.title, date: page.date, tags: page.tags, body: page.body },
        page.template
      );
    },
    afterBuild(pages, ctx) {
      if (!ctx.outputDir) return;
      const engine = getTemplateEngine(ctx.templatesDir);
      fs.writeFileSync(path.join(ctx.outputDir, 'index.html'), engine.renderIndex(pages), 'utf-8');
    },
  };
}

import fs from 'fs';
import http from 'http';
import path from 'path';
import chokidar, { FSWatcher } from 'chokidar';
import { WebSocket, WebSocketServer } from 'ws';
import { Plugin, PluginContext } from '../src/plugin';

const DEFAULT_PORT = 3000;
const LIVE_RELOAD_PATH = '/__livereload';
const REBUILD_DEBOUNCE_MS = 100;

const CONTENT_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.txt': 'text/plain; charset=utf-8',
};

const LIVE_RELOAD_SCRIPT = `
<script>
(function () {
  var socket = new WebSocket('ws://' + location.host + '${LIVE_RELOAD_PATH}');
  socket.addEventListener('message', function (event) {
    if (event.data === 'reload') {
      location.reload();
    }
  });
})();
</script>
`;

function injectLiveReload(html: string): string {
  if (html.includes('</body>')) {
    return html.replace('</body>', `${LIVE_RELOAD_SCRIPT}</body>`);
  }
  return html + LIVE_RELOAD_SCRIPT;
}

function resolveRequestedFile(outputDir: string, urlPath: string): string | undefined {
  const decoded = decodeURIComponent(urlPath.split('?')[0] ?? '/');
  let relative = decoded === '/' ? '/index.html' : decoded;
  if (relative.endsWith('/')) relative += 'index.html';

  const root = path.resolve(outputDir);
  const resolved = path.resolve(root, `.${relative}`);
  if (resolved !== root && !resolved.startsWith(root + path.sep)) {
    return undefined;
  }
  return resolved;
}

function sendNotFound(res: http.ServerResponse): void {
  res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end('404 Not Found');
}

function serveFile(outputDir: string, urlPath: string, res: http.ServerResponse): void {
  const filePath = resolveRequestedFile(outputDir, urlPath);
  if (!filePath || !fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    sendNotFound(res);
    return;
  }

  const ext = path.extname(filePath).toLowerCase();
  const contentType = CONTENT_TYPES[ext] ?? 'application/octet-stream';

  if (ext === '.html') {
    const html = fs.readFileSync(filePath, 'utf-8');
    res.writeHead(200, { 'Content-Type': contentType });
    res.end(injectLiveReload(html));
    return;
  }

  res.writeHead(200, { 'Content-Type': contentType });
  fs.createReadStream(filePath).pipe(res);
}

export interface DevServerPluginOptions {
  port?: number;
  /** Triggers a full build pass (via the owning SSGEngine); called on every watched file change. */
  rebuild: () => void;
}

export interface DevServerPlugin extends Plugin {
  getPort(): number;
}

/**
 * Serves the output directory over HTTP, watches content/templates for
 * changes, and notifies connected browsers over WebSocket after each
 * rebuild. `afterBuild` (run by the engine for every build pass, including
 * ones triggered by this plugin's own watcher) is what broadcasts reloads.
 */
export function devServerPlugin(options: DevServerPluginOptions): DevServerPlugin {
  const { rebuild, port = DEFAULT_PORT } = options;
  let httpServer: http.Server | undefined;
  let wss: WebSocketServer | undefined;
  let watcher: FSWatcher | undefined;
  let rebuildTimer: NodeJS.Timeout | undefined;
  let actualPort = port;

  const broadcastReload = (): void => {
    if (!wss) return;
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  };

  const scheduleRebuild = (): void => {
    if (rebuildTimer) clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(() => {
      rebuild();
    }, REBUILD_DEBOUNCE_MS);
  };

  return {
    name: 'dev-server',

    getPort: () => actualPort,

    async onStart(ctx: PluginContext) {
      const outputDir = ctx.outputDir as string;

      httpServer = http.createServer((req, res) => {
        serveFile(outputDir, req.url ?? '/', res);
      });
      wss = new WebSocketServer({ server: httpServer, path: LIVE_RELOAD_PATH });

      watcher = chokidar.watch([ctx.contentDir, ctx.templatesDir], { ignoreInitial: true });
      watcher.on('add', scheduleRebuild);
      watcher.on('change', scheduleRebuild);
      watcher.on('unlink', scheduleRebuild);

      const listening = new Promise<number>((resolve, reject) => {
        httpServer!.once('error', reject);
        httpServer!.listen(port, () => {
          httpServer!.removeListener('error', reject);
          const address = httpServer!.address();
          resolve(typeof address === 'object' && address ? address.port : port);
        });
      });
      const watcherReady = new Promise<void>((resolve) => watcher!.once('ready', resolve));

      const [resolvedPort] = await Promise.all([listening, watcherReady]);
      actualPort = resolvedPort;
    },

    afterBuild() {
      broadcastReload();
    },

    async onEnd() {
      if (rebuildTimer) clearTimeout(rebuildTimer);
      if (watcher) await watcher.close();
      if (wss) {
        const socket = wss;
        await new Promise<void>((resolve) => socket.close(() => resolve()));
        for (const client of socket.clients) client.terminate();
      }
      if (httpServer) {
        const server = httpServer;
        await new Promise<void>((resolve, reject) => server.close((err) => (err ? reject(err) : resolve())));
      }
    },
  };
}

import fs from 'fs';
import path from 'path';
import { Plugin } from './plugin';
import { markdownPlugin } from '../plugins/markdown-plugin';
import { templatePlugin } from '../plugins/template-plugin';

export interface SSGConfig {
  plugins: Plugin[];
}

const DEFAULT_CONFIG_FILE = 'ssg.config.ts';

function defaultPlugins(): Plugin[] {
  return [markdownPlugin(), templatePlugin()];
}

/**
 * Loads the build-time plugin pipeline from `ssg.config.ts` in `cwd`. Falls
 * back to the built-in markdown + template plugins when no config file is
 * present, or when it doesn't export a plugin list, so `ssg build` keeps
 * working without any project scaffolding.
 */
export function loadConfig(cwd: string, configFile: string = DEFAULT_CONFIG_FILE): SSGConfig {
  const configPath = path.resolve(cwd, configFile);
  if (!fs.existsSync(configPath)) {
    return { plugins: defaultPlugins() };
  }

  const required = require(configPath);
  const config: Partial<SSGConfig> | undefined = required?.default ?? required;
  const plugins = config?.plugins;
  return { plugins: Array.isArray(plugins) && plugins.length > 0 ? plugins : defaultPlugins() };
}

import { markdownPlugin } from './plugins/markdown-plugin';
import { templatePlugin } from './plugins/template-plugin';
import { SSGConfig } from './src/config';

const config: SSGConfig = {
  plugins: [markdownPlugin(), templatePlugin()],
};

export default config;

import fs from 'fs';
import path from 'path';
import { loadConfig } from './config';
import { SSGEngine, findMarkdownFiles } from './engine';
import { PluginContext } from './plugin';
import { Page } from './types';

export { findMarkdownFiles };

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
}

export interface BuildResult {
  pages: Page[];
  outputDir: string;
}

export function defaultTemplatesDir(): string {
  return path.resolve(process.cwd(), 'templates');
}

export function buildPage(contentDir: string, filename: string, templatesDir: string = defaultTemplatesDir()): Page {
  const engine = new SSGEngine(loadConfig(process.cwd()).plugins);
  const ctx: PluginContext = { contentDir, templatesDir };
  return engine.buildFile(contentDir, filename, ctx);
}

/**
 * Runs a full build pass through the plugin pipeline and writes the
 * resulting pages to `ctx.outputDir`. Shared by the one-shot `build()` below
 * and by the dev server, which reruns it on every watched file change using
 * the same engine instance (so plugins like the dev server's own reload
 * broadcast fire on every pass).
 */
export function buildAndWrite(engine: SSGEngine, ctx: PluginContext): Page[] {
  const outputDir = ctx.outputDir;
  if (!outputDir) {
    throw new Error('outputDir is required to write build output');
  }
  fs.mkdirSync(outputDir, { recursive: true });
  const pages = engine.runBuild(ctx);
  for (const page of pages) {
    fs.writeFileSync(path.join(outputDir, page.outputPath), page.html, 'utf-8');
  }
  return pages;
}

export function build(options: BuildOptions): BuildResult {
  const { contentDir, outputDir, templatesDir = defaultTemplatesDir() } = options;
  const engine = new SSGEngine(loadConfig(process.cwd()).plugins);
  const ctx: PluginContext = { contentDir, outputDir, templatesDir };
  const pages = buildAndWrite(engine, ctx);
  return { pages, outputDir };
}

import path from 'path';
import { BuildOptions, buildAndWrite } from './build';
import { loadConfig } from './config';
import { SSGEngine } from './engine';
import { PluginContext } from './plugin';
import { clearTemplateEngineCache } from './templates';
import { devServerPlugin } from '../plugins/dev-server-plugin';

export interface ServeOptions extends BuildOptions {
  port?: number;
}

export interface DevServer {
  port: number;
  close(): Promise<void>;
}

const DEFAULT_PORT = 3000;

function defaultTemplatesDir(): string {
  return path.resolve(process.cwd(), 'templates');
}

export async function startServer(options: ServeOptions): Promise<DevServer> {
  const {
    contentDir,
    outputDir,
    templatesDir = defaultTemplatesDir(),
    port = DEFAULT_PORT,
  } = options;

  const ctx: PluginContext = { contentDir, outputDir, templatesDir };
  const buildPlugins = loadConfig(process.cwd()).plugins;

  let engine: SSGEngine;
  const runBuild = (): void => {
    try {
      clearTemplateEngineCache(templatesDir);
      buildAndWrite(engine, ctx);
    } catch (err) {
      console.error('Rebuild failed:', err instanceof Error ? err.message : err);
    }
  };

  const dsPlugin = devServerPlugin({ port, rebuild: runBuild });
  engine = new SSGEngine([...buildPlugins, dsPlugin]);

  runBuild();
  await engine.start(ctx);

  return {
    port: dsPlugin.getPort(),
    close: async () => {
      await engine.end(ctx);
    },
  };
}

